window.TASK_BANKS[51] = {"version":1,"topicId":51,"tasks":[{"id":"51.1","codeLang":"python","answer":"hello","answerLang":"text","explanation":"connect создаёт отдельную базу в памяти. CREATE TABLE описывает два поля; первая вставленная запись получает id 1 автоматически. В SQL стоит ?, а значение hello передано отдельно в кортеже из одного элемента: запятая после строки обязательна. SELECT выбирает только title, fetchone() даёт ('hello',), row[0] — строку hello. Именно она печатается без кавычек. Это соединение видит свою вставку до commit; закрытие уничтожит временную базу, а не сохранит её в файл.","verified":"да","wrong":["('hello',)","1","None"]},{"id":"51.2","codeLang":"python","answer":"return con.execute('SELECT COUNT(*) FROM items').fetchone()[0]","answerLang":"python","explanation":"В запросе SELECT COUNT(*) FROM items звёздочка означает подсчёт строк: запись с NULL в title тоже учитывается. COUNT(title) решал бы другой вопрос — сколько значений title не равны NULL; пустая строка при этом всё равно считается значением. Запрос возвращает одну строку с одним числом, например (2,). fetchone() получает кортеж, [0] извлекает число для return. В заготовке две записи, поэтому готовый print выводит 2. Чтение не должно сохранять, отменять или менять вставки вызывающего кода. Своё соединение он закроет сам.","verified":"да","check":{"append":"import sqlite3\nfrom contextlib import closing\nwith closing(sqlite3.connect(':memory:')) as _db:\n    _db.execute('CREATE TABLE items(id INTEGER PRIMARY KEY, title TEXT)')\n    _actual = count_items(_db)\n    assert type(_actual) is int and _actual == 0, f'Пустая таблица: ожидалось целое 0, получено {_actual!r}'\n    assert not _db.in_transaction, 'Чтение количества не должно начинать изменение данных'\n    _db.executemany('INSERT INTO items(title) VALUES (?)', [('x',), (None,), ('',), ('z',)])\n    _before = _db.execute('SELECT id, title FROM items ORDER BY id').fetchall()\n    _changes = _db.total_changes\n    _actual = count_items(_db)\n    assert type(_actual) is int and _actual == 4, f'Считайте все строки, включая NULL и пустой текст: ожидалось 4, получено {_actual!r}'\n    assert _db.execute('SELECT id, title FROM items ORDER BY id').fetchall() == _before and _db.total_changes == _changes, 'count_items только читает данные'\n    assert _db.in_transaction, 'Фиксировать или отменять чужую транзакцию функция чтения не должна'\n    _db.rollback()\n    assert count_items(_db) == 0, 'После отмены вставки таблица снова пуста'\nprint('OK')","expect":"OK"}},{"id":"51.3","codeLang":"python","answer":"['Ada']","answerLang":"text","explanation":"executemany вставляет две записи: Ada с 10 и Bob с 7. WHERE оставляет только 10 >= 8. SELECT name возвращает одну колонку, но строка результата всё ещё кортеж: fetchall() даёт [('Ada',)]. Включение берёт r[0] из каждого кортежа и создаёт ['Ada']. Это список из одной Python-строки, не один кортеж и не строка Ada без списка. В этом примере совпадение одно; когда порядок нескольких результатов важен, его задают явно через ORDER BY.","verified":"да","wrong":["[('Ada',)]","['Ada', 'Bob']","Ada"]},{"id":"51.4","codeLang":"python","answer":"con.execute('INSERT INTO users(name, score) VALUES (?, ?)', (name, score))","answerLang":"python","explanation":"У INSERT два места для значений — имя и балл. Второй аргумент execute передаёт данные в том же порядке, поэтому кавычка внутри имени остаётся частью имени. Именованные места и словарь параметров решают ту же задачу. Ручная замена кавычек с последующей f-строкой не выполняет требование отделить параметры от SQL. Каждое обращение должно добавлять запись, не удалять прежних пользователей с таким именем. Вставка сразу видна тому же соединению, но ещё может быть отменена вызывающим кодом. Готовый print в заготовке отдельно читает балл Ada и выводит 10; функция его не печатает.","verified":"да","check":{"append":"import sqlite3\nfrom contextlib import closing\n_bindings = []\ndef _remember_sql(_sql, _parameters):\n    _bindings.append((_sql, tuple(_parameters.values()) if isinstance(_parameters, dict) else tuple(_parameters)))\nclass _BindingCursor(sqlite3.Cursor):\n    def execute(self, sql, parameters=()):\n        _remember_sql(sql, parameters)\n        return super().execute(sql, parameters)\n    def executemany(self, sql, parameters):\n        parameters = list(parameters)\n        for row in parameters:\n            _remember_sql(sql, row)\n        return super().executemany(sql, parameters)\nclass _BindingConnection(sqlite3.Connection):\n    def execute(self, sql, parameters=()):\n        _remember_sql(sql, parameters)\n        return super().execute(sql, parameters)\n    def executemany(self, sql, parameters):\n        parameters = list(parameters)\n        for row in parameters:\n            _remember_sql(sql, row)\n        return super().executemany(sql, parameters)\n    def cursor(self, *args, **kwargs):\n        if not args:\n            kwargs.setdefault('factory', _BindingCursor)\n        return super().cursor(*args, **kwargs)\nwith closing(sqlite3.connect(':memory:', factory=_BindingConnection)) as _db:\n    _db.execute('CREATE TABLE users(name TEXT, score INTEGER)')\n    for _name, _score in [(\"O'Neil\", -2), ('X', 0), ('', 7), (\"'); DROP TABLE users; --\", 5), ('X', 11)]:\n        _before = _db.execute('SELECT name, score FROM users ORDER BY rowid').fetchall()\n        _bindings.clear()\n        add_user(_db, _name, _score)\n        assert any(_name in _params and _score in _params for _sql, _params in _bindings), 'Передайте name и score отдельно от SQL: допустимы ? и именованные параметры'\n        _actual = _db.execute('SELECT name, score FROM users ORDER BY rowid').fetchall()\n        assert _actual == _before + [(_name, _score)], f'Должна добавиться ровно одна новая строка без потери старых: {_actual!r}'\n        assert _db.in_transaction, 'Транзакцию фиксирует вызывающий код, не add_user'\n    _db.rollback()\n    assert _db.execute('SELECT COUNT(*) FROM users').fetchone()[0] == 0, 'Вся серия должна оставаться доступной для отмены вызывающим кодом'\nprint('OK')","expect":"OK"}},{"id":"51.5","codeLang":"python","answer":"Это открывает SQL-инъекции: злонамеренная строка может изменить запрос.\nНужны плейсхолдеры ? и передача значений отдельно параметрами.","answerLang":"text","explanation":"В склеенной строке кавычка из пользовательского текста может закончить SQL-значение; следующие символы тогда становятся командой или условием. SQL-инъекция — изменение смысла запроса данными. Плейсхолдер оставляет место для значения, а sqlite3 получает это значение отдельным аргументом: даже текст, похожий на условие SQL, остаётся обычным текстом. Варианты ? с кортежем и :name со словарём — оба параметризованные. Параметры предназначены для значений, а не для названий таблиц или колонок. Не следует проверять безопасность на чужой базе: здесь используются только вымышленные записи во временной базе.","verified":"не требуется"},{"id":"51.6","codeLang":"python","answer":"cloud","answerLang":"text","explanation":"Настройка row_factory сделана до запроса, поэтому fetchone() создаёт sqlite3.Row. SELECT выбрал колонку title, и row['title'] извлекает её значение cloud. Это то же поле, что row[0]; в print не попадают имя колонки или SQL-команда. Сам sqlite3.Row не обычный dict, хотя отдельное dict(row) могло бы построить словарь. Если запрос не найдёт строк, fetchone() вернёт None — обращаться к полю такого результата нельзя без проверки.","verified":"да","wrong":["('cloud',)","{'title': 'cloud'}","title"]},{"id":"51.7","codeLang":"python","answer":"conn.execute('CREATE TABLE hi(name TEXT)')\nconn.execute(\"INSERT INTO hi VALUES ('Ada')\")\nrows = conn.execute('SELECT name FROM hi').fetchall()","answerLang":"python","explanation":"CREATE TABLE создаёт hi, INSERT — одну запись, SELECT выбирает её name. fetchall() возвращает список кортежей, поэтому печатается [('Ada',)], а не ['Ada']. В заготовке уже открыт conn и уже есть print(rows); повторять их не нужно. Ada здесь фиксированный литерал, не внешний пользовательский ввод. Для передаваемых пользователем значений нужны параметры. Соединение видит незавершённую вставку и без commit; это ещё не проверка сохранности данных. В файле commit позволил бы открыть запись новым соединением, а ':memory:' исчезнет при закрытии даже после commit. В каждом запуске учебного контейнера файловая система тоже новая.","verified":"да"},{"id":"51.8","codeLang":"python","answer":"def find_users(connection, name):\n    rows = connection.execute(\"SELECT id FROM users WHERE name = ? ORDER BY id\", (name,))\n    return [row[0] for row in rows]","answerLang":"python","explanation":"Значение name передаётся отдельно от SQL, поэтому кавычки и похожие на SQL символы не меняют условие. Выбираем именно колонку id и извлекаем первое поле каждой строки. ORDER BY id задаёт возрастание; сортировка уже выбранных чисел в Python тоже допустима. DISTINCT здесь не нужен: условие просит все совпавшие записи, даже если id повторился. Сравнение имени точное, без lower и изменения регистра. При отсутствии строк итерация создаёт пустой список. Поиск не присваивает себе владение соединением или незавершённой транзакцией вызывающего кода.","verified":"да","hint":"Кавычка в имени — обычные данные. Как передать её, не редактируя SQL-текст?","check":{"append":"import sqlite3\nfrom contextlib import closing\n_bindings = []\ndef _remember_sql(_sql, _parameters):\n    _bindings.append((_sql, tuple(_parameters.values()) if isinstance(_parameters, dict) else tuple(_parameters)))\nclass _BindingCursor(sqlite3.Cursor):\n    def execute(self, sql, parameters=()):\n        _remember_sql(sql, parameters)\n        return super().execute(sql, parameters)\n    def executemany(self, sql, parameters):\n        parameters = list(parameters)\n        for row in parameters:\n            _remember_sql(sql, row)\n        return super().executemany(sql, parameters)\nclass _BindingConnection(sqlite3.Connection):\n    def execute(self, sql, parameters=()):\n        _remember_sql(sql, parameters)\n        return super().execute(sql, parameters)\n    def executemany(self, sql, parameters):\n        parameters = list(parameters)\n        for row in parameters:\n            _remember_sql(sql, row)\n        return super().executemany(sql, parameters)\n    def cursor(self, *args, **kwargs):\n        if not args:\n            kwargs.setdefault('factory', _BindingCursor)\n        return super().cursor(*args, **kwargs)\nwith closing(sqlite3.connect(':memory:', factory=_BindingConnection)) as _db:\n    _db.execute('CREATE TABLE users(id INTEGER, name TEXT)')\n    _data = [(3, 'Ada'), (1, 'Ada'), (2, \"O'Neil\"), (7, ''), (4, 'ada'), (6, \"' OR 1=1 --\"), (8, 'Ada'), (8, 'Ada')]\n    _db.executemany('INSERT INTO users VALUES (?, ?)', _data)\n    _changes = _db.total_changes\n    for _name, _expected in [('Ada', [1, 3, 8, 8]), (\"O'Neil\", [2]), (\"' OR 1=1 --\", [6]), ('missing', []), ('', [7]), ('ada', [4])]:\n        _bindings.clear()\n        _actual = find_users(_db, _name)\n        assert any(_name in _params for _sql, _params in _bindings), 'Имя должно передаваться SQL-параметром, а не встраиваться в текст команды'\n        assert isinstance(_actual, list) and all(type(_id) is int for _id in _actual) and _actual == _expected, f'find_users({_name!r}): ожидалось {_expected!r}, получено {_actual!r}'\n        assert _db.execute('SELECT id, name FROM users ORDER BY rowid').fetchall() == _data and _db.total_changes == _changes, 'Поиск не должен менять записи'\n        assert _db.in_transaction, 'Поиск не должен фиксировать или отменять вставки вызывающего кода'\nprint('OK')","expect":"OK"}},{"id":"51.9","codeLang":"python","answer":"def transfer(connection, source, target, amount):\n    with connection:\n        balance = connection.execute(\"SELECT balance FROM accounts WHERE id = ?\", (source,)).fetchone()[0]\n        if balance < amount:\n            return False\n        connection.execute(\"UPDATE accounts SET balance = balance - ? WHERE id = ?\", (amount, source))\n        connection.execute(\"UPDATE accounts SET balance = balance + ? WHERE id = ?\", (amount, target))\n    return True","answerLang":"python","explanation":"Сначала читается остаток source. Если он меньше amount, возвращается False без UPDATE. Равенство разрешено: после перевода остаток будет нулевым. Два UPDATE внутри with connection относятся к одной транзакции при оговорённых настройках. Успех фиксирует изменения, исключение отменяет незавершённую транзакцию и распространяется наружу. Если зафиксировать списание до зачисления, откат второй команды уже не вернёт списанные деньги — это ошибка даже при правильных ответах на удачных примерах. Обычный with connection не закрывает соединение; завершить commit/rollback явно через try тоже допустимо. Вход в with не создаёт вложенную независимую транзакцию, поэтому условие заранее исключает чужие незавершённые изменения. Конкуренция нескольких переводов этим учебным решением не покрыта.","verified":"да","hint":"Что должно произойти с первым UPDATE, если второй завершился ошибкой?","check":{"append":"import sqlite3\nfrom contextlib import closing\nfrom pathlib import Path\nfrom tempfile import TemporaryDirectory\nwith TemporaryDirectory() as _folder:\n    _path = Path(_folder) / 'accounts.sqlite'\n    with closing(sqlite3.connect(_path)) as _db:\n        _db.execute('CREATE TABLE accounts(id INTEGER PRIMARY KEY, balance INTEGER)')\n        _db.executemany('INSERT INTO accounts VALUES (?, ?)', [(1, 100), (2, 20), (3, 7)])\n        _db.commit()\n        for _source, _target, _amount, _expected, _balances in [(1, 2, 30, True, [(1, 70), (2, 50), (3, 7)]), (2, 1, 51, False, [(1, 70), (2, 50), (3, 7)]), (2, 1, 50, True, [(1, 120), (2, 0), (3, 7)]), (3, 2, 7, True, [(1, 120), (2, 7), (3, 0)]), (1, 3, 120, True, [(1, 0), (2, 7), (3, 120)]), (2, 3, 8, False, [(1, 0), (2, 7), (3, 120)])]:\n            _actual = transfer(_db, _source, _target, _amount)\n            assert _actual is _expected, f'transfer({_source}, {_target}, {_amount}): ожидалось {_expected!r}, получено {_actual!r}'\n            assert _db.execute('SELECT id, balance FROM accounts ORDER BY id').fetchall() == _balances, 'Измените только два выбранных счёта на заданную сумму'\n            assert not _db.in_transaction, 'Успешный перевод должен быть зафиксирован, незавершённая транзакция не должна оставаться'\n            with closing(sqlite3.connect(_path)) as _reader:\n                assert _reader.execute('SELECT id, balance FROM accounts ORDER BY id').fetchall() == _balances, 'Другое соединение должно видеть зафиксированный результат'\n    with closing(sqlite3.connect(':memory:')) as _db:\n        _db.execute('CREATE TABLE accounts(id INTEGER PRIMARY KEY, balance INTEGER CHECK(balance <= 100))')\n        _db.executemany('INSERT INTO accounts VALUES (?, ?)', [(11, 80), (22, 98)])\n        _db.commit()\n        try:\n            transfer(_db, 11, 22, 5)\n        except sqlite3.IntegrityError:\n            pass\n        else:\n            raise AssertionError('Ошибка второго UPDATE должна распространиться, а не превращаться в True/False')\n        assert _db.execute('SELECT id, balance FROM accounts ORDER BY id').fetchall() == [(11, 80), (22, 98)], 'При отказе зачисления списание тоже должно отмениться'\n        assert not _db.in_transaction, 'После ошибки нужен завершённый откат'\nprint('OK')","expect":"OK"}}]};
